recipes.code:
{
  "inputs": [
    {
      "id": "candidatehub-token",
      "type": "promptString",
      "description": "Personal Access Token minted at https://www.aicandidatehub.com/account/mcp-tokens (format chmcp_…). Required by all API-backed tools; the server starts and lists tools without it.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@aicandidatehub/mcp@0.5.2"
      ],
      "env": {
        "CANDIDATEHUB_TOKEN": "${input:candidatehub-token}",
        "CANDIDATEHUB_API_BASE": "<candidatehub-api-base>"
      }
    }
  }
}
